  "knowledge": "Base Station Communication Stability Index (BSCSI)",
  "description": "Evaluates the stability and reliability of polar base station communication systems",
  "definition": "BSCSI = CRI \u00d7 (1 + 0.2 \u00d7 signalmetrics.radio_strength_dbm \u00f7 100) \u00d7 (1 - 0.01 \u00d7 (1000 - signalmetrics.latency_ms))"
}

{
  "id": 20,
  "knowledge": "reliabilityindex",
  "description": "Illustrates the significance of reliability index measurements in equipment durability.",
  "definition": "The reliability index typically ranges from 0 to 1, where values below 0.5 indicate equipment that fails frequently and requires constant maintenance, values between 0.5-0.8 represent equipment with occasional failures that require regular maintenance, and values above 0.8 indicate highly reliable equipment with minimal downtime."
}

{
  "id": 14,
  "knowledge": "Communication Zone Status",
  "description": "Evaluates the communication coverage and reliability in different operational zones.",
  "definition": "A zone is classified as having 'Reliable Coverage' when equipment within it maintains a CRI > 7, has active satellite connections (signalmetrics.satellite_status = 'Connected'), and supports emergency beacon functionality (emergencybeaconstatus != 'Inactive')."
}

{
  "id": 45,
  "knowledge": "Communication Network Resilience Assessment (CNRA)",
  "description": "Assesses the resilience and interference resistance of polar communication networks",
  "definition": "Communication networks are assessed as having 'High Resilience' (CRI > 0.8 and BSCSI > 0.85), 'Medium Resilience' (CRI > 0.6 and BSCSI > 0.7), or 'Low Resilience' (other cases)."
}
